package com.mamtrex.hospital.bloodbank;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="blood_units") public class BloodUnit extends BaseEntity { private String unitCode; private String bloodType; private String component; private String expiresOn; private String status; protected BloodUnit(){} public BloodUnit(String unitCode, String bloodType, String component, String expiresOn, String status){this.unitCode=unitCode; this.bloodType=bloodType; this.component=component; this.expiresOn=expiresOn; this.status=status;} public String getUnitCode(){return unitCode;} public String getBloodType(){return bloodType;} public String getComponent(){return component;} public String getExpiresOn(){return expiresOn;} public String getStatus(){return status;} }
